    fn no_action_when_everything_fine() {
        let mut state = GameState::new(2);
        state.create_object(CardId(1), PlayerId(0), Zone::Battlefield, Some(2), Some(3));

        assert!(!check_state_based_actions(&mut state));
    }
}

